# RT TASK-20260925-2333ea: toy cell, labellers, certificates and v2 routing.
import random
from lib import *

def ord_mod(a, n):
    k, x = 1, a % n
    while x != 1: x = x * a % n; k += 1
    return k

def phi_factors(n):
    d = ord_mod(2, n)
    phi = (1 << n) - 1  # 1 + X + ... + X^(n-1)
    facs = []; rest = phi
    for f in range(1 << d, 1 << (d + 1)):
        if f & 1 and pdivmod(rest, f)[1] == 0 and irreducible(f):
            facs.append(f); rest = pdivmod(rest, f)[0]
    assert rest == 1, (n, facs)
    return sorted(facs), d

def kernel_of_g(F, g):
    n = F.n
    def L(x):
        s = 0; t = x
        for i in range(pdeg(g) + 1):
            if (g >> i) & 1: s ^= t
            t = F.sq(t)
        return s
    # columns L(z^i); kernel over F_2 by elimination on augmented rows
    rows = [(L(1 << i), 1 << i) for i in range(n)]
    basis = []; piv_rows = []
    for v, tag in rows:
        for pv, pt in piv_rows:
            if v ^ pv < v: v ^= pv; tag ^= pt
        if v == 0: basis.append(tag)
        else:
            piv_rows.append((v, tag)); piv_rows.sort(key=lambda t: -t[0])
    # re-reduce basis to be safe
    W = {0}
    for b in basis: W |= {w ^ b for w in W}
    for w in W: assert L(w) == 0
    return sorted(W), len(basis)

class Cell:
    def __init__(self, n, a, a6=1, gidx=0, M=None, log=None):
        self.n, self.a = n, a
        self.F = F = GF(n, M)
        self.E = E = Curve(F, a, a6)
        self.t = 1 if a == 1 else -1
        self.order = lucas_order(n, self.t)
        self.fac = factorint(self.order)
        self.r = r = max(self.fac); self.h = h = self.order // r
        self.k = n
        self.proj = h * pow(h, -1, r)
        rng = random.Random(subseed("P0-%d-%d" % (n, a)))
        while True:
            x = rng.randrange(2, 1 << n); pts = E.points_at_x(x)
            if pts:
                P0 = E.mul(h, pts[0])
                if P0 is not None: break
        assert E.mul(r, P0) is None
        self.P0 = P0
        s = sqrt_mod(self.t * self.t - 8, r); i2 = pow(2, -1, r)
        self.lam_cands = sorted({(self.t + s) * i2 % r, (self.t - s) * i2 % r})
        tP0 = E.frob(P0)
        self.lam = next(c for c in self.lam_cands if E.mul(c, P0) == tP0)
        lam = self.lam
        self.AR2 = {"lambda^k=1": pow(lam, n, r) == 1, "lambda!=1": lam != 1,
                    "k|r-1": (r - 1) % n == 0}
        self.mu = [pow(lam, i, r) for i in range(n)]
        self.facs, self.d = phi_factors(n)
        f1, f2 = self.facs[0], self.facs[1]
        self.divisors = [f1, f2, pmul(3, f1), pmul(3, f2)]
        self.g = self.divisors[gidx]
        self.W, self.dimW = kernel_of_g(F, self.g)
        self.build_base()
        self.cache_mul = {}

    def piG(self, P):
        return self.E.mul(self.proj, P)

    def build_base(self):
        E, F, n = self.E, self.F, self.n
        self.FW = []; self.piGmap = {}
        for x in self.W:
            if x in (0, 1): continue
            for P in E.points_at_x(x):
                Q = self.piG(P)
                if Q is not None:
                    self.FW.append(P); self.piGmap[P] = Q
        self.FWset = set(self.FW)
        # class orbits: key by x(Q); orbit = {x(Q)^(2^e)}
        self.orbit_of_x = {}; self.reps = []
        for P in self.FW:
            Q = self.piGmap[P]
            if Q[0] in self.orbit_of_x: continue
            xs = [F.frob(Q[0], e) for e in range(n)]
            assert len(set(xs)) == n, "class orbit length != k (IR-7)"
            xm = min(xs); ys = self.E.points_at_x(xm)
            QO = min(ys, key=lambda p: p[1])  # m-J1-4: lesser y
            oid = len(self.reps); self.reps.append(QO)
            for xx in xs: self.orbit_of_x[xx] = oid
        # point orbits
        self.porbit = {}; self.preps = []
        for P in self.FW:
            if P in self.porbit: continue
            orb = [E.frob(P, e) for e in range(n)]
            assert len(set(orb)) == n, "point orbit length != n (IR-7)"
            PO = min(orb); oid = len(self.preps); self.preps.append(PO)
            for Q in orb: self.porbit[Q] = oid

    def smul(self, s, P):
        key = (s, P)
        if key not in self.cache_mul: self.cache_mul[key] = self.E.mul(s, P)
        return self.cache_mul[key]

    # ---- labellers: return (oid, e, eps) for the class of a leg --------
    def label(self, P, mode="correct"):
        E, n = self.E, self.n
        Q = self.piG(P) if P not in self.piGmap else self.piGmap[P]
        oid = self.orbit_of_x.get(Q[0])
        if oid is None: return None
        QO = self.reps[oid]
        if mode == "M2s-rep": QO = E.neg(QO)
        for e in range(n):
            ee = (-e) % n if mode == "M2" else e
            T = E.frob(QO, ee)
            if T == Q: lab = (oid, e, 1); break
            if T == E.neg(Q): lab = (oid, e, -1); break
        else: raise AssertionError("no label")
        if mode == "M2s-leg": lab = (lab[0], lab[1], -lab[2])
        return lab
    def plabel(self, P, mode="correct"):
        oid = self.porbit.get(P)
        if oid is None: return None
        PO = self.preps[oid]
        for e in range(self.n):
            ee = (-e) % self.n if mode == "M2" else e
            if self.E.frob(PO, ee) == P: return (oid, e, 1)
        raise AssertionError

    def orbit_polys(self, legs, mode="correct", basis="class"):
        r, n = self.r, self.n; f = {}
        for P in legs:
            lab = self.label(P, mode) if basis == "class" else self.plabel(P, mode)
            oid, e, eps = lab
            f.setdefault(oid, [0] * n)[e] = (f.setdefault(oid, [0] * n)[e] + eps) % r
        return {o: c for o, c in f.items() if any(c)}

scripts.instr.py:
# RT TASK-20260925-2333ea: instruments and v2 routing (P2-2 AR-1 -> P2-2b certs -> P2-3 ranks -> P2-6).
import random
from lib import *
from cell import Cell

INSTR = {
    "CONTROL": dict(builder="curve", lab="correct", qeval="lam"),
    "M1":      dict(builder="copy",  lab="correct", qeval="lam"),
    "M2":      dict(builder="curve", lab="M2",      qeval="lam"),
    "M2s-rep": dict(builder="curve", lab="M2s-rep", qeval="lam"),
    "M2s-leg": dict(builder="curve", lab="M2s-leg", qeval="lam"),
    "M3":      dict(builder="curve", lab="correct", qeval="laminv"),
    "M4":      dict(builder="shift1", lab="correct", qeval="lam"),
}

def build_rows_legs(c, legs0, builder):
    k = c.k; out = []
    for j in range(k):
        if builder == "copy": out.append(list(legs0))
        elif builder == "shift1" and j >= 1: out.append([c.E.frob(P, j + 1) for P in legs0])
        else: out.append([c.E.frob(P, j) for P in legs0])
    return out

def shift(poly, j, k):
    return [poly[(e - j) % k] for e in range(k)]

class Readings:
    """Certificate readings. cb: 'literal' ([lambda^j] R on the full target) or 'piG'.
    cq: 'literal' (recompute f_O(lambda_AR2)) or 'ranked' (the ranked quotient row).
    cl: 'canonical' (contract Q_O) or 'instrument' (the labeller's own representative)."""
    def __init__(self, cb="literal", cq="literal", cl="canonical"):
        self.cb, self.cq, self.cl = cb, cq, cl

def rep_for(c, oid, I, rd):
    QO = c.reps[oid]
    if rd.cl == "instrument" and I["lab"] == "M2s-rep": QO = c.E.neg(QO)
    return QO

def cert_label(c, P, I, rd, which="class"):
    r = c.r
    if which == "class":
        oid, e, eps = c.label(P, I["lab"])
        lhs = c.E.mul(c.proj, P)
        rhs = c.smul(pow(c.lam, e, r), rep_for(c, oid, I, rd))
        if eps < 0: rhs = c.E.neg(rhs)
        return lhs == rhs
    else:
        lab = c.plabel(P, "M2" if I["lab"] == "M2" else "correct")
        oid, e, _ = lab
        return P == c.E.frob(c.preps[oid], e)

def quot_point(c, I):
    return c.lam if I["qeval"] == "lam" else pow(c.lam, -1, c.r)

def ranked_quot_row(c, polys, I):
    z = quot_point(c, I)
    return {o: peval(f, z, c.r) for o, f in polys.items()}

def cert_quot(c, legs0, R, I, rd):
    polys = c.orbit_polys(legs0, I["lab"])
    if rd.cq == "literal": coords = {o: peval(f, c.lam, c.r) for o, f in polys.items()}
    else: coords = ranked_quot_row(c, polys, I)
    S = None
    for o, v in coords.items():
        S = c.E.add(S, c.smul(v, rep_for(c, o, I, rd)))
    return S == c.E.mul(c.proj, R)

def cert_bind(c, legs_rows, R, I, rd):
    """returns None if pass, else the failing sub-clause"""
    E, r, k = c.E, c.r, c.k
    legs0 = legs_rows[0]
    p0 = c.orbit_polys(legs0, I["lab"])
    for j in range(1, k):
        lj = legs_rows[j]
        if lj != [E.frob(P, j) for P in legs0]: return ("legs_j != tau^j(legs_0)", j)
        sj = E.sumpts(lj); tR = E.frob(R, j)
        if sj != tR: return ("sum legs_j != tau^j(R)", j)
        if rd.cb == "literal":
            if tR != c.smul(pow(c.lam, j, r), R): return ("tau^j(R) != [lambda^j] R", j)
        else:
            if E.mul(c.proj, tR) != c.smul(pow(c.lam, j, r), E.mul(c.proj, R)): return ("piG: tau^j(R) != [lambda^j] R", j)
        for P in lj:
            if not cert_label(c, P, I, rd): return ("CERT-LABEL row j", j)
        pj = c.orbit_polys(lj, I["lab"])
        if pj != {o: shift(f, j, k) for o, f in p0.items()}: return ("curve-side row != shift", j)
    return None

def ranks(c, legs_rows, I):
    r, k = c.r, c.k
    polys_rows = [c.orbit_polys(l, I["lab"]) for l in legs_rows]
    orbs = sorted(set(o for p in polys_rows for o in p))
    raw = [sum((p.get(o, [0] * k) for o in orbs), []) for p in polys_rows]
    pp_rows = [c.orbit_polys(l, I["lab"] if I["lab"] == "M2" else "correct", "point") for l in legs_rows]
    porbs = sorted(set(o for p in pp_rows for o in p))
    rawp = [sum((p.get(o, [0] * k) for o in porbs), []) for p in pp_rows]
    z = quot_point(c, I)
    quot = [[peval(p.get(o, [0] * k), z, r) for o in orbs] for p in polys_rows]
    Z = c.kerg_roots
    kerg = [[peval(p.get(o, [0] * k), zz, r) for o in orbs for zz in Z] for p in polys_rows] if Z else None
    p0, pp0 = polys_rows[0], pp_rows[0]
    ev_raw = sum(1 for zz in c.mu if any(peval(f, zz, r) for f in p0.values()))
    ev_pt = sum(1 for zz in c.mu if any(peval(f, zz, r) for f in pp0.values()))
    ev_q = 1 if any(peval(f, c.lam, r) for f in p0.values()) else 0
    ev_kg = sum(1 for zz in Z if any(peval(f, zz, r) for f in p0.values()))
    out = {}
    for name, M, ev in (("raw_class", raw, ev_raw), ("raw_point", rawp, ev_pt), ("quotient", quot, ev_q), ("kerg", kerg, ev_kg)):
        if M is None: out[name] = (0, 0, ev); continue
        a = rank_A(M, r); b = rank_B(M, r) if a != ev else a
        out[name] = (a, b, ev)
    return out

def route_relation(c, src, legs0, R, I, rd):
    E = c.E
    # P2-2 AR-1
    if not all(P in c.FWset for P in legs0) or E.sumpts(legs0) != R or E.mul(c.proj, R) is None:
        return {"src": src, "admitted": False, "first_rule": "AR-1 (not admitted)"}
    legs_rows = build_rows_legs(c, legs0, I["builder"])
    # P2-2b in order: CERT-LABEL row 0, CERT-QUOT row 0, CERT-BIND rows 1..k-1
    for P in legs0:
        if not cert_label(c, P, I, rd): return {"src": src, "admitted": True, "first_rule": "IR-16 (CERT-LABEL row 0)"}
    if not cert_quot(c, legs0, R, I, rd): return {"src": src, "admitted": True, "first_rule": "IR-15 (CERT-QUOT row 0)"}
    fb = cert_bind(c, legs_rows, R, I, rd)
    if fb: return {"src": src, "admitted": True, "first_rule": "IR-17 (CERT-BIND: %s, j=%d)" % fb}
    # P2-3 ranks, P2-6
    rk = ranks(c, legs_rows, I)
    cand = [b for b, (a, bb, ev) in rk.items() if a != ev]
    if any(rk[b][0] != rk[b][1] for b in cand): return {"src": src, "admitted": True, "first_rule": "IR-14", "ranks": rk}
    if cand:
        # P2-6 v2_addendum: certificates re-run on the exported rows
        ok = cert_quot(c, legs0, R, I, rd) and cert_bind(c, legs_rows, R, I, rd) is None
        if not ok: return {"src": src, "admitted": True, "first_rule": "P2-6 re-run cert fails (IR-15..17)", "ranks": rk}
        oc = "O-REFUTE-Q" if "quotient" in cand else "O-REFUTE-L3"
        return {"src": src, "admitted": True, "first_rule": "P2-6 candidate -> " + oc, "ranks": rk}
    return {"src": src, "admitted": True, "first_rule": "none (ranked; = EVAL)", "ranks": rk}

def relations(c, key, n1=8, n3=12, n32=12, n4=6):
    E = c.E; rng = random.Random(subseed("rels-" + key)); rels = []
    for _ in range(n1):
        R = E.mul(rng.randrange(1, c.r), c.P0); seen = set()
        for P1 in c.FW:
            P2 = E.add(R, E.neg(P1))
            if P2 in c.FWset:
                pk = tuple(sorted([P1, P2]))
                if pk not in seen: seen.add(pk); rels.append(("RS-1", list(pk), R))
    for m, cnt in ((2, n3), (3, n32)):
        for _ in range(cnt):
            legs = [rng.choice(c.FW) for _ in range(m)]
            rels.append(("RS-3 m=%d" % m, legs, E.sumpts(legs)))
    for sg in (-1, 1):
        for _ in range(n4):
            P = rng.choice(c.FW); d = rng.randrange(1, c.k); P2 = E.frob(P, d)
            if sg < 0: P2 = E.neg(P2)
            rels.append(("RS-4" + ("minus" if sg < 0 else "plus"), [P, P2], E.add(P, P2)))
    return rels

def kerg_roots(c):
    ghat = [(c.g >> i) & 1 for i in range(pdeg(c.g) + 1)]
    return [z for z in c.mu if peval(ghat, z, c.r) == 0]

