}
def inval(t):
    ks = [k.split(" | ")[-1] for k in t]
    return any(k.startswith("IR") or k.startswith("P2-6 re-run") for k in ks)

c0 = Cell(17, 0); c0.kerg_roots = kerg_roots(c0)
