def tally(c, rels, I, rd):
    t = {}
    for src, legs, R in rels:
        fr = route_relation(c, src, legs, R, I, rd)["first_rule"]
        fr = fr.split(", j=")[0] if ", j=" in fr else fr
        t[src + " | " + fr] = t.get(src + " | " + fr, 0) + 1
    return t
