    b = tally(c0, g4rels, I, rd); m1 = tally(c0, g4rels, INSTR["M1"], rd); m2 = tally(c0, g4rels, INSTR["M2"], rd)
    return (inval(m1) and inval(m2) and not inval(b)), b

