scripts.e4scope.py:
# e4scope.py -- epoch-4 J4 (iii)-(v) enumeration aid (TASK-20260925-2333ea).
# Walks every string leaf of the four bound producer files (parsed YAML), splits
# each into sentences, and flags every sentence matching a broad scope lexicon
# (scope, consequence, margin, unit movement, gain, claimant, transfer,
# extrapolation, plus the two decisions and the correction CORR item 1(d) names).
# The flagged list is then classified BY HAND (the classification lives in the
# report); this script only guarantees the candidate set is exhaustive for the
# lexicon and records counts and digests.
import yaml, re, hashlib, json, sys
FILES = {
 'SPEC': 'experiments/EXP-BINSTD-178742/specification.yaml',
 'HYP': 'ledger/hypotheses/H-BINSTD-ce4f38.yaml',
 'AUDIT': 'coordination/goals/GOAL-ECDLP2M-001/batches/BATCH-b67954/design/TASK-20260925-46739d/proof-search-map-audit.yaml',
 'WS': 'coordination/goals/GOAL-ECDLP2M-001/batches/BATCH-b67954/design/TASK-20260925-46739d/revision-worksheet.yaml',
}
LEX = re.compile(r"(scope|consequen|margin|\bmov(e|es|ed|ement|ing)\b|\bgain|saving|claimant|\bclaimed\b|correct(s|ion|ed)?\b|\blowers?\b|transfer|extrapolat|reachab|decision_it|\bunit\b|per-orbit|per orbit|row by row|\beach (row|koblitz|frobenius)|every (frobenius|koblitz|row)|index-calculus|attacker|\bbits?\b|log2|\bcost|secur|weak|safe|cheap|deployed|exponent|speed|\brho\b|factor[- ]k|divided by k|/k\b|99ce20|f0a9c7|649e25|sota_delta|1a081a|c48e7d|saving-b|\bC3\b|dependenc|closes?\b|closed|closure|dead\b|affect)", re.I)
def leaves(o, path=''):
    if isinstance(o, dict):
        for k, v in o.items(): yield from leaves(v, f'{path}.{k}' if path else str(k))
    elif isinstance(o, list):
        for i, v in enumerate(o): yield from leaves(v, f'{path}[{i}]')
    elif isinstance(o, str):
        yield path, o
def sentences(t):
    t = ' '.join(t.split())
    return [s.strip() for s in re.split(r'(?<=[.;!?])\s+(?=[A-Z(\'"])', t) if s.strip()]
out = {}; tot = {}
root = '/home/user/crypto-autoresearcher/'
for tag, p in FILES.items():
    b = open(root + p, 'rb').read()
    y = yaml.safe_load(b)
    cands = []; nsent = 0
    for path, txt in leaves(y):
        for s in sentences(txt):
            nsent += 1
            if LEX.search(s): cands.append((path, s))
    tot[tag] = {'sha256': hashlib.sha256(b).hexdigest(), 'sentences': nsent, 'flagged': len(cands),
                'flagged_digest': hashlib.sha256(json.dumps(cands).encode()).hexdigest()}
    out[tag] = cands
print(json.dumps(tot, indent=1))
if len(sys.argv) > 1:
    tag = sys.argv[1]
    for i, (path, s) in enumerate(out[tag]):
        print(f'{tag}#{i:03d} {path} :: {s[:260]}')
